from lib import *
S = SS('x57')
steps = [
    step("每个阶段在哪个线程(主线程叫 main)。没有调度器:订阅、源、订阅者都在 main。subscribeOn(boundedElastic)(哪怕写在链的末尾):订阅、源、map 之后、订阅者全在 boundedElastic-1——它改的是订阅(也就是源)所在的线程。publishOn(parallel):订阅和源仍在 main,publishOn 之后全在 parallel-1。两者合用:订阅与源在 boundedElastic-1,publishOn 之后的下游在 parallel-2。两个 subscribeOn(single 再 boundedElastic)只有离源最近的第一个生效,全程是 single-1;两个 publishOn(single 再 boundedElastic):每个都生效,第一个之后在 single-1,第二个之后在 boundedElastic-1。", t=tl(S(1)), mark=lidx(S(1), 'subscribeOn(single) 再 subscribeOn', 'publishOn(single) 再 publishOn'), done=lidx(S(1), '没有任何调度器', 'subscribeOn(boundedElastic)(放在', 'publishOn(parallel) 放在', 'subscribeOn(boundedElastic) + publishOn'), b=bars([['subscribeOn 改变的阶段数(订阅、源、其后全部)', 4, '4'], ['publishOn 只改变它之后的阶段数', 2, '2'], ['两个 subscribeOn 实际生效的个数', 1, '1(最靠近源的)'], ['两个 publishOn 实际生效的个数', 2, '2']], 4, done=[0, 1, 3], mark=[2]), kv=KV([['subscribeOn', '决定订阅/源所在线程,位置无所谓,只有最靠近源的生效'], ['publishOn', '决定它之后的线程,可以多次切换'], ['不加调度器', '订阅者的线程决定一切(这里是 main)'], ['组合', '源与阻塞在 subscribeOn 的线程,下游在 publishOn 的线程']], ['subscribeOn'])),
    step("定时与异步源自带线程。Mono.delay(50ms) 之后的下游在 parallel-3 上执行。在线程 my-completer 里 complete 一个 CompletableFuture,Mono.fromFuture 之后的 doOnNext 就在 my-completer 里执行——谁触发完成,下游就在谁的线程上继续。下游想换线程,要自己写 publishOn。", t=tl(S(2)), mark=lidx(S(2), 'my-completer'), done=lidx(S(2), 'delay 完成后'), b=bars([['delay 下游的线程(parallel-3)', 1, 'parallel-3'], ['fromFuture 下游的线程(my-completer)', 1, 'my-completer']], 1, done=[0], mark=[1]), kv=KV([['Mono.delay', '之后在 parallel 线程上'], ['fromFuture', '之后在完成它的线程上'], ['结论', '下游线程由上游来源决定,不是订阅者'], ['想要换线程', 'publishOn']], ['结论'])),
    step("阻塞的源放在哪个线程。Mono.fromCallable 里睡 300 ms,不加 subscribeOn:subscribe() 这一行本身就用了 310 ms,调用线程被卡住;加 subscribeOn(boundedElastic):subscribe() 只用了 2 ms,整体仍然是 305 ms 才完成,但卡住的是 boundedElastic 的线程,调用线程立刻返回。subscribeOn 不会让阻塞代码变快,只是决定谁来被阻塞。", t=tl(S(3)), mark=lidx(S(3), '不加 subscribeOn'), done=lidx(S(3), 'subscribeOn(boundedElastic)'), b=bars([['不加 subscribeOn:subscribe() 用时 ms', 310, '310'], ['加 subscribeOn:subscribe() 用时 ms', 2, '2'], ['加 subscribeOn:整体完成 ms', 305, '305']], 310, mark=[0], done=[1, 2]), kv=KV([['不加 subscribeOn', '阻塞发生在调用线程'], ['subscribeOn(boundedElastic)', '阻塞挪到 boundedElastic 线程'], ['总耗时', '不变,只是换了谁被阻塞'], ['适用', '包装阻塞的老代码(JDBC、文件)']], ['subscribeOn(boundedElastic)'])),
    step("同一条链上的元素与并行。Flux.range(1, 6).publishOn(parallel).map:6 个元素全部在 parallel-4 上——一个订阅者对应一个线程,元素是顺序处理的,不会因为 publishOn 就并行。flatMap 里 4 个阻塞 300 ms 的内层:内层不加调度器,4 个都在 main 上顺序执行,总耗时 1235 ms;内层加 subscribeOn(boundedElastic),分别落在 boundedElastic-1 … -4,总耗时 304 ms。要并行,是 flatMap 加每个内层 subscribeOn,不是单独的 publishOn。", t=tl(S(4)), mark=lidx(S(4), '内层不加调度器'), done=lidx(S(4), 'Flux.range(1, 6)', '内层加 subscribeOn'), b=bars([['内层不加调度器:总耗时 ms', 1235, '1235(4 × 300 顺序)'], ['内层加 subscribeOn:总耗时 ms', 304, '304(4 个并行)'], ['publishOn 之后 6 个元素用到的线程数', 1, '1']], 1235, mark=[0], done=[1, 2]), kv=KV([['publishOn', '一个订阅者一个线程,元素顺序处理'], ['flatMap 内层不切线程', '阻塞内层顺序执行'], ['flatMap + 内层 subscribeOn', '内层并行'], ['并行度', '受 flatMap 并发数和调度器线程数共同限制']], ['flatMap + 内层 subscribeOn'])),
    step("调度器的线程数。availableProcessors = 10;200 个阻塞 20 ms 的任务放到 Schedulers.parallel() 上,一共只用了 10 个线程(parallel-1 … parallel-10),与 CPU 核数一致,其余任务排队。同样的任务数换成 boundedElastic:40 个并发阻塞任务用了 40 个线程。parallel 是给不阻塞的计算用的,在它上面做阻塞操作,10 个线程很快被占满;boundedElastic 线程会按需创建,是阻塞操作该去的地方。", t=tl(S(5)), mark=lidx(S(5), 'parallel-1'), done=lidx(S(5), '40 个并发阻塞任务'), b=bars([['parallel 上 200 个任务用的线程数', 10, '10'], ['boundedElastic 上 40 个任务用的线程数', 40, '40']], 40, mark=[0], done=[1]), kv=KV([['parallel', '线程数 = CPU 核数,别阻塞'], ['boundedElastic', '按需创建线程,放阻塞调用'], ['single', '单线程'], ['线程名', 'parallel-N / boundedElastic-N / single-N']], ['parallel'])),
]
A = mkartx('x57', 57, 'Spring,Reactor,publishOn,subscribeOn,Schedulers,线程模型,真实验证,动画演示',
    '实测 Reactor 的线程切换:subscribeOn 决定订阅与源所在线程且只有最靠近源的生效,publishOn 决定它之后的线程且可以多次切换;Mono.delay 之后在 parallel 线程,fromFuture 之后在完成它的线程;阻塞的源不加 subscribeOn 会卡住调用线程(subscribe() 用了 310 ms),加了之后 2 ms 返回;flatMap 里内层加 subscribeOn 才并行(1235 ms 降到 304 ms);parallel 线程数等于核数,阻塞操作该去 boundedElastic。',
    'subscribeOn 和 publishOn 到底有什么区别?写在链的哪里有关系吗?多次调用谁生效?阻塞的老代码该放在哪个调度器?为什么 flatMap 里要加 subscribeOn 才并行?这篇在 Reactor 3.8.7 上把每个阶段的线程名打印出来。',
    [('310 → 2 ms', '阻塞源不加 / 加 subscribeOn(boundedElastic) 时,subscribe() 这一行的耗时'), ('1235 → 304 ms', 'flatMap 里 4 个阻塞 300 ms 的内层,不加 / 加 subscribeOn 的总耗时'), ('10', '200 个任务放到 parallel 调度器上实际用到的线程数(等于核数)')],
    [('线程在哪里切换', '<p>subscribeOn 影响订阅与源,publishOn 影响它之后的阶段。</p>'),
     ('异步源的线程', '<p>下游线程由上游来源决定。</p>'),
     ('阻塞的源', '<p>subscribeOn 决定谁来被阻塞,不会让阻塞变快。</p>'),
     ('并行', '<p>flatMap 加内层 subscribeOn 才并行。</p>'),
     ('调度器', '<p>parallel 的线程数等于核数,阻塞操作去 boundedElastic。</p>')],
    steps,
    [ENV_X + '。用 reactor-core 3.8.7 的单个 Java 程序,不依赖 Spring 容器;机器为 10 个逻辑核心;线程名 parallel-N、boundedElastic-N 的序号随运行顺序变化,只有线程类别可复现',
     '没有验证:Schedulers.newParallel 与自定义调度器;Schedulers.boundedElastic 的上限(默认线程数上限与任务队列上限)被触及时的行为;虚拟线程调度器(见第 60 篇);Hooks.onScheduleHook;publishOn 的 prefetch 对线程切换次数的影响(见第 56 篇);WebFlux 中 Netty event loop 与这些调度器的关系(见第 58 篇)'],
    '线程切换')
